use crate::types::{AbiSig, CombinatorAbi, ElemClass, RuntimeEntry};

/// Build a [`RuntimeEntry`] from name, typed params, return type, tier, and docs.
macro_rules! rt {
    ($name:literal, ($($p:expr),*) -> $ret:expr, $tier:expr, $docs:literal) => {
        RuntimeEntry {
            name: $name,
            sig: AbiSig {
                params: &[$($p),*],
                ret: $ret,
            },
            tier: $tier,
            docs: $docs,
            noreturn: false,
            unwinds: false,
            combinator: None,
            mints_string: false,
        }
    };
}

/// Like [`rt!`] but marks the entry as `noreturn` so the LLVM emitter
/// annotates the declaration with `noreturn cold nounwind`. Only for
/// functions that provably never return (abort / panic paths).
macro_rules! rt_nr {
    ($name:literal, ($($p:expr),*) -> $ret:expr, $tier:expr, $docs:literal) => {
        RuntimeEntry {
            name: $name,
            sig: AbiSig {
                params: &[$($p),*],
                ret: $ret,
            },
            tier: $tier,
            docs: $docs,
            noreturn: true,
            unwinds: false,
            combinator: None,
            mints_string: false,
        }
    };
}

/// Like [`rt!`] but marks the entry as may-unwind, so the LLVM
/// declaration drops `nounwind`. For a shim a Gossamer fault crosses on
/// its way to whoever reports it - the handler-dispatch shims, which let a
/// panicking handler reach the server loop that answers 500 and names the
/// request.
macro_rules! rt_unwind {
    ($name:literal, ($($p:expr),*) -> $ret:expr, $tier:expr, $docs:literal) => {
        RuntimeEntry {
            name: $name,
            sig: AbiSig {
                params: &[$($p),*],
                ret: $ret,
            },
            tier: $tier,
            docs: $docs,
            noreturn: false,
            unwinds: true,
            combinator: None,
            mints_string: false,
        }
    };
}

/// Like [`rt_nr!`] but marks the entry as may-unwind: the LLVM
/// declaration keeps `noreturn cold` and drops `nounwind`. Only for
/// the panic helper, which raises a Rust panic on the goroutine path.
macro_rules! rt_nr_unwind {
    ($name:literal, ($($p:expr),*) -> $ret:expr, $tier:expr, $docs:literal) => {
        RuntimeEntry {
            name: $name,
            sig: AbiSig {
                params: &[$($p),*],
                ret: $ret,
            },
            tier: $tier,
            docs: $docs,
            noreturn: true,
            unwinds: true,
            combinator: None,
            mints_string: false,
        }
    };
}

/// Like [`rt!`] but declares the element crossing of a sequence-combinator
/// shim: the combinator it implements, the class it reads its input buffer
/// as, and the class of the element it produces where the symbol
/// distinguishes one. The MIR lowering derives the symbol from that triple
/// instead of spelling it, so a crossing with no shim behind it is a missing
/// registry row rather than a wrong call or an undefined symbol at link time.
macro_rules! rt_iter {
    ($name:literal, ($($p:expr),*) -> $ret:expr, $tier:expr, $comb:literal, $elem:expr, $result:expr, $docs:literal) => {
        RuntimeEntry {
            name: $name,
            sig: AbiSig {
                params: &[$($p),*],
                ret: $ret,
            },
            tier: $tier,
            docs: $docs,
            noreturn: false,
            unwinds: false,
            combinator: Some(CombinatorAbi {
                combinator: $comb,
                elem: $elem,
                result: $result,
            }),
            mints_string: false,
        }
    };
}

/// Like [`rt!`] but declares that the symbol's `Ptr` return is a freshly
/// allocated `String` the caller owns. The runtime spells the same fact as
/// `-> *mut c_char`; `registry_string_returns_are_declared_owned` in
/// `gossamer-cli`'s dispatch-consistency suite holds the two together, so a
/// new string-minting shim cannot reach the compiler undeclared.
///
/// The drop pass schedules a release for a local that takes such a result.
/// A shim whose answer aliases its accumulator - the in-place `String`
/// append family - keeps the plain [`rt!`] form.
macro_rules! rt_str {
    ($name:literal, ($($p:expr),*) -> $ret:expr, $tier:expr, $docs:literal) => {
        RuntimeEntry {
            name: $name,
            sig: AbiSig {
                params: &[$($p),*],
                ret: $ret,
            },
            tier: $tier,
            docs: $docs,
            noreturn: false,
            unwinds: false,
            combinator: None,
            mints_string: true,
        }
    };
}

